<?php
require_once __DIR__.'/config.php'; require_admin(); $pdo=db(); $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$equipmentId=(int)($_POST['equipment_id']??0);$date=trim($_POST['maintenance_date']??'');$type=trim($_POST['maintenance_type']??'');$by=trim($_POST['performed_by']??'');$cost=trim($_POST['cost']??'0');$details=trim($_POST['details']??'');$next=trim($_POST['next_due']??'');
 if(!$equipmentId)$errors[]='Choose equipment.';if(!$date)$errors[]='Maintenance date is required.';if(!$type)$errors[]='Maintenance type is required.';if($cost!==''&&!is_numeric($cost))$errors[]='Cost must be numeric.';
 if(!$errors){$st=$pdo->prepare('INSERT INTO maintenance(equipment_id,maintenance_date,maintenance_type,performed_by,cost,details,next_due) VALUES(?,?,?,?,?,?,?)');$st->execute([$equipmentId,$date,$type,$by,(float)$cost,$details,$next]);flash('Maintenance record saved.');redirect('maintenance.php');}
}
$equipment=$pdo->query('SELECT id,asset_tag,name FROM equipment ORDER BY name')->fetchAll();
$filterId=(int)($_GET['equipment_id']??0);$sql='SELECT m.*,e.asset_tag,e.name FROM maintenance m JOIN equipment e ON e.id=m.equipment_id';$params=[];if($filterId){$sql.=' WHERE e.id=?';$params[]=$filterId;}$sql.=' ORDER BY m.maintenance_date DESC,m.id DESC';$st=$pdo->prepare($sql);$st->execute($params);$logs=$st->fetchAll();
$pageTitle='Maintenance';require 'header.php';
?>
<div class="page-heading"><div><div class="eyebrow">PREVENTIVE CARE</div><h1>Maintenance log</h1><p>Record repairs, inspections and planned service dates for network equipment.</p></div></div><?php show_flash(); ?>
<?php if($errors): ?><div class="alert error"><ul><?php foreach($errors as $err): ?><li><?=e($err)?></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="maintenance-grid"><section class="panel"><div class="panel-heading"><div><h2>Log maintenance</h2><p>Record a service or repair activity</p></div></div><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Equipment <em>*</em></label><select name="equipment_id" required><option value="">Select asset</option><?php foreach($equipment as $eq): ?><option value="<?=(int)$eq['id']?>" <?=($filterId===(int)$eq['id'])?'selected':''?>><?=e($eq['asset_tag'].' — '.$eq['name'])?></option><?php endforeach; ?></select><label>Maintenance date <em>*</em></label><input type="date" name="maintenance_date" required value="<?=e(date('Y-m-d'))?>"><label>Maintenance type <em>*</em></label><select name="maintenance_type" required><option value="">Choose type</option><option>Inspection</option><option>Preventive maintenance</option><option>Repair</option><option>Configuration</option><option>Replacement</option><option>Cleaning</option></select><label>Performed by</label><input name="performed_by" placeholder="Technician or service provider"><label>Cost (KES)</label><input type="number" name="cost" min="0" step="0.01" value="0"><label>Next service due</label><input type="date" name="next_due"><label>Work details</label><textarea name="details" rows="3" placeholder="Describe the inspection, repair or work done"></textarea><button class="btn primary full" type="submit">Save maintenance record</button></form></section>
<section class="panel"><div class="panel-heading"><div><h2>Service history</h2><p><?=count($logs)?> maintenance record(s)</p></div><form method="get"><select name="equipment_id" onchange="this.form.submit()"><option value="">All equipment</option><?php foreach($equipment as $eq): ?><option value="<?=(int)$eq['id']?>" <?=$filterId===(int)$eq['id']?'selected':''?>><?=e($eq['asset_tag'])?></option><?php endforeach; ?></select></form></div>
<?php if(!$logs): ?><div class="empty-block"><span>⚒</span><b>No maintenance records yet</b><p>Use the form to record your first service activity.</p></div><?php else: ?><div class="service-list"><?php foreach($logs as $log): ?><div class="service-item"><div class="service-icon">⚒</div><div class="service-content"><div class="service-title"><b><?=e($log['maintenance_type'])?></b><span class="date-chip"><?=e($log['maintenance_date'])?></span></div><div class="service-asset"><?=e($log['asset_tag'].' · '.$log['name'])?></div><p><?=e($log['details'] ?: 'No additional details provided.')?></p><div class="service-meta">By <?=e($log['performed_by'] ?: 'Not specified')?> · KES <?=number_format((float)$log['cost'],2)?><?php if($log['next_due']): ?> · Next due <?=e($log['next_due'])?><?php endif; ?></div></div></div><?php endforeach; ?></div><?php endif; ?></section></div>
<?php require 'footer.php'; ?>
